const path = require("node:path");
const { lstat, realpath, mkdir, open, link, unlink } = require("node:fs/promises");
const { randomUUID } = require("node:crypto");

const readStdin = () => new Promise((resolve, reject) => {
  let value = "";
  process.stdin.setEncoding("utf8");
  process.stdin.on("data", (chunk) => { value += chunk; });
  process.stdin.on("end", () => resolve(value));
  process.stdin.on("error", reject);
});
const isWithin = (root, candidate) => {
  const relative = path.relative(root, candidate);
  return relative === "" || (!path.isAbsolute(relative) && relative !== ".." && !relative.startsWith(`..${path.sep}`));
};
const identity = (stat) => `${stat.dev}:${stat.ino}`;
const mustDirectory = (stat, target) => {
  if (stat.isSymbolicLink() || !stat.isDirectory()) throw new Error(`Unsafe output parent: ${target}`);
};
const statOrMissing = async (target) => {
  try { return await lstat(target); }
  catch (error) { if (error.code === "ENOENT") return null; throw error; }
};

(async () => {
  const candidate = await readStdin();
  const root = await realpath(process.cwd());
  const relativeTarget = "docs/analysis/components/file/bin/csl-agent-kit.js.md";
  const target = path.resolve(root, relativeTarget);
  const namespace = path.resolve(root, "docs/analysis/components/file");
  if (!isWithin(root, target) || !isWithin(namespace, target)) throw new Error("Unsafe active report path");

  const rootStat = await lstat(root);
  mustDirectory(rootStat, root);
  const identities = new Map([[root, identity(rootStat)]]);
  const parents = [];
  let current = root;
  for (const segment of ["docs", "analysis", "components", "file", "bin"]) {
    current = path.join(current, segment);
    parents.push(current);
    const stat = await statOrMissing(current);
    if (stat) {
      mustDirectory(stat, current);
      identities.set(current, identity(stat));
    }
  }
  const existingTarget = await statOrMissing(target);
  if (existingTarget) throw new Error("Active report appeared before publication");

  for (const parent of parents) {
    let stat = await statOrMissing(parent);
    if (!stat) {
      try { await mkdir(parent); }
      catch (error) { if (error.code !== "EEXIST") throw error; }
      stat = await lstat(parent);
    }
    mustDirectory(stat, parent);
    const prior = identities.get(parent);
    if (prior && prior !== identity(stat)) throw new Error(`Output parent identity changed: ${parent}`);
    identities.set(parent, identity(stat));
  }

  const recheckParents = async () => {
    for (const parent of [root, ...parents]) {
      const stat = await lstat(parent);
      mustDirectory(stat, parent);
      if (identities.get(parent) !== identity(stat)) throw new Error(`Output parent identity changed: ${parent}`);
    }
    const resolvedParent = await realpath(path.dirname(target));
    if (resolvedParent !== path.dirname(target)) throw new Error("Output parent canonical path changed");
  };

  await recheckParents();
  if (await statOrMissing(target)) throw new Error("Active report appeared before temp creation");

  const temp = path.join(path.dirname(target), `.${path.basename(target)}.${process.pid}.${randomUUID()}.tmp`);
  let owned = false;
  let handle;
  try {
    handle = await open(temp, "wx");
    owned = true;
    try { await handle.writeFile(candidate, { encoding: "utf8" }); }
    finally { await handle.close(); handle = null; }

    await recheckParents();
    try { await link(temp, target); }
    catch (error) {
      if (error.code === "EEXIST") throw new Error("Active report appeared during publication");
      throw error;
    }
    await unlink(temp);
    owned = false;
    console.log(target);
  } finally {
    if (handle) await handle.close();
    if (owned) {
      try { await unlink(temp); }
      catch (error) { if (error.code !== "ENOENT") throw error; }
    }
  }
})().catch((error) => { console.error(error.message); process.exitCode = 1; });
